<template><SuperAdminLayout><main class="notice-list"><header><div><h1>Notifications List</h1><p>Email and SMS notifications sent to customer system admins</p></div><div><RouterLink to="/super-admin/notifications/sms-format">＋ New Notification</RouterLink><button @click="exportCsv">▧ Export PDF</button><button @click="print">▣ Print</button></div></header><section class="summary"><article v-for="card in cards" :key="card.label"><i>{{card.icon}}</i><div><b>{{card.label}}</b><strong>{{card.value}}</strong></div></article></section><section class="filters"><h2>⚱ Filters</h2><label>Notification No.<input v-model="filters.search" placeholder="Enter notification no."></label><label>Method<select v-model="filters.channel"><option value="">Select method</option><option value="email">Email</option><option value="sms">SMS</option></select></label><label>Status<select v-model="filters.status"><option value="">Select status</option><option value="sent">Sent</option><option value="scheduled">Scheduled</option><option value="failed">Failed</option></select></label><label>Search<input v-model="filters.search" placeholder="Search by subject or keywords"></label><button @click="load">⌕ Apply Filters</button><button class="reset" @click="reset">↻ Reset</button></section><section class="card"><h2>Notifications List</h2><div class="table"><table><thead><tr><th>No.</th><th>Notification No.</th><th>Customer Name</th><th>Notification Type</th><th>Method</th><th>Subject</th><th>Recurring Info</th><th>Posted Date</th><th>Expiry Date</th><th>Status</th><th>View Details</th></tr></thead><tbody><tr v-for="(row,index) in data.rows||[]" :key="row.id"><td>{{index+1}}</td><td>{{row.notification_no}}</td><td>{{row.customer}}</td><td>{{row.type}}</td><td>{{row.channel}}</td><td>{{row.subject}}</td><td>{{row.recurring}}</td><td>{{format(row.date)}}</td><td>{{format(row.expires_at)}}</td><td><span :class="['pill',row.status.toLowerCase()]">{{row.status}}</span></td><td><button class="view">View</button></td></tr><tr v-if="!(data.rows||[]).length"><td colspan="11">No notifications found.</td></tr></tbody></table></div></section></main></SuperAdminLayout></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import{RouterLink}from'vue-router';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';const data=ref({}),filters=reactive({search:'',status:'',channel:''}),format=v=>v?new Date(v).toLocaleDateString():'—',cards=computed(()=>{const x=data.value.summary||{};return[{label:'Total Notifications',value:x.total||0,icon:'✉'},{label:'Scheduled',value:x.scheduled||0,icon:'◴'},{label:'Sent',value:x.sent||0,icon:'➤'},{label:'Expired',value:x.expired||0,icon:'⌛'},{label:'Failed',value:x.failed||0,icon:'⚠'}]});async function load(){data.value=(await client.get('/super-admin/notifications',{params:filters})).data.data||{}}function reset(){Object.assign(filters,{search:'',status:'',channel:''});load()}function print(){window.print()}function exportCsv(){const h=['notification_no','customer','type','channel','subject','status'],csv=[h,...(data.value.rows||[]).map(r=>h.map(k=>JSON.stringify(r[k]||'')))].map(r=>r.join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv]));a.download='notifications.csv';a.click()}onMounted(load)</script>
<style scoped>.notice-list{color:#071d63}.notice-list header{display:flex;justify-content:space-between;gap:16px;margin-bottom:17px}.notice-list h1{margin:0;font-size:2rem}.notice-list header p{margin:4px 0;color:#607093}.notice-list header div:last-child{display:flex;gap:10px}.notice-list header a,.notice-list header button,.filters button{border:1px solid #cbd9ed;border-radius:6px;background:#fff;color:#092b73;padding:11px 16px;font-weight:700;text-decoration:none}.notice-list header a,.filters button{background:#0755dc;color:#fff;border-color:#0755dc}.summary{display:grid;grid-template-columns:repeat(5,1fr);gap:14px;margin-bottom:16px}.summary article{display:flex;gap:15px;align-items:center;padding:15px;border:1px solid #dce5f3;border-radius:8px;background:#fff}.summary i{display:grid;place-items:center;width:42px;height:42px;border-radius:50%;background:#edf3ff;color:#0755dc;font-style:normal;font-size:1.4rem}.summary b,.summary strong{display:block}.summary b{font-size:.78rem}.summary strong{font-size:1.65rem;color:#0755dc}.filters,.card{border:1px solid #dce5f3;border-radius:8px;background:#fff;padding:14px;margin-bottom:14px}.filters{display:grid;grid-template-columns:repeat(4,1fr) auto auto;gap:12px;align-items:end}.filters h2{grid-column:1/-1;margin:0;font-size:1rem}.filters label{display:grid;gap:5px;font-size:.7rem;font-weight:800}.filters input,.filters select{height:37px;border:1px solid #cad8ed;border-radius:5px;padding:0 10px}.filters .reset{background:#fff;color:#092b73;border-color:#cbd9ed}.card{padding:0;overflow:hidden}.card h2{padding:11px 14px;margin:0;color:#0755dc;font-size:1rem}.table{overflow:auto}table{min-width:1180px;width:100%;border-collapse:collapse;font-size:.76rem}th{background:linear-gradient(90deg,#06235f,#063887);color:#fff}th,td{padding:8px;border:1px solid #dbe4ef;text-align:left}td{font-weight:600}.pill{display:inline-block;min-width:58px;padding:3px 7px;border-radius:4px;text-align:center}.sent{color:#078338;background:#eaf9ef}.scheduled{color:#0755dc;background:#edf5ff}.failed{color:#d62424;background:#fff0f0}.view{border:1px solid #d5e0ef;border-radius:4px;background:#fff;color:#0755dc;padding:4px 10px;font-weight:700}@media(max-width:900px){.summary{grid-template-columns:repeat(2,1fr)}.filters{grid-template-columns:1fr 1fr}.notice-list header{display:block}.notice-list header div:last-child{margin-top:12px;flex-wrap:wrap}}@media print{.sa-sidebar,.sa-topbar,.filters,.notice-list header div:last-child{display:none!important}}</style>
